/**
 * Reads a compiled Soroban contract's embedded contract spec — the
 * `contractspecv0` custom section of the contract WASM — and turns it into a
 * normalized, renderer-friendly model.
 *
 * The spec is the contract's own machine-readable description of its
 * entry points, argument types, return types, struct/enum definitions and
 * error codes. It is generated by `soroban-sdk`'s macros at compile time, so
 * it is always exactly in sync with the compiled contract — which is what
 * makes it a trustworthy source for the SDK's TypeScript types.
 *
 * See `scripts/codegen.ts` for the CLI that drives this, and
 * `scripts/render-contract-types.ts` for the model -> TypeScript renderer.
 */
import { xdr } from "@stellar/stellar-sdk";

/** The WASM custom section `soroban-sdk` embeds the contract spec in. */
export const CONTRACT_SPEC_SECTION = "contractspecv0";

/**
 * The Soroban "primitive" spec types — the ones a `ScSpecTypeDef` can carry
 * without any extra payload.
 */
export type PrimitiveTypeName =
  | "void"
  | "bool"
  | "u32"
  | "i32"
  | "u64"
  | "i64"
  | "u128"
  | "i128"
  | "u256"
  | "i256"
  | "timepoint"
  | "duration"
  | "address"
  | "muxed_address"
  | "string"
  | "symbol"
  | "bytes"
  | "error"
  | "val";

/**
 * A normalized contract-spec type.
 *
 * The spec's own encoding is a XDR union with a variant per type; this
 * model keeps the same information in a shape that is easy to walk when
 * rendering TypeScript.
 */
export type SpecType =
  | { kind: "primitive"; name: PrimitiveTypeName }
  /** `BytesN<n>` — a fixed-length byte array. */
  | { kind: "bytesN"; length: number }
  | { kind: "vec"; element: SpecType }
  | { kind: "option"; value: SpecType }
  | { kind: "tuple"; values: SpecType[] }
  | { kind: "map"; key: SpecType; value: SpecType }
  /** `Result<T, E>` — the contract's own error type is always `E`. */
  | { kind: "result"; ok: SpecType; error: SpecType }
  /** A user-defined type (struct/enum/union) declared by the contract. */
  | { kind: "udt"; name: string };

/** One named field of a struct, or one parameter of a function or event. */
export interface SpecField {
  name: string;
  doc: string;
  type: SpecType;
}

/** A `#[contracttype] struct` declared by the contract. */
export interface SpecStruct {
  name: string;
  doc: string;
  fields: SpecField[];
}

/** A `#[contracttype] enum` declared by the contract. */
export interface SpecEnum {
  name: string;
  doc: string;
  cases: SpecEnumCase[];
}

export interface SpecEnumCase {
  name: string;
  doc: string;
  /** The variant's numeric value — the value that goes on the wire. */
  value: number;
}

/** A contract event, as declared with `#[contractevent]`. */
export interface SpecEvent {
  name: string;
  doc: string;
  /** The event's fixed topic prefix, e.g. `["zk", "verify"]`. */
  topics: string[];
  params: SpecField[];
}

/** One exported entry point of the contract. */
export interface SpecFunction {
  name: string;
  doc: string;
  inputs: SpecField[];
  /** The function's return type, or `undefined` when it returns nothing. */
  output?: SpecType;
}

/**
 * A contract's `#[contracterror]` enum — the numeric codes a failed
 * contract call carries back to the caller.
 */
export interface SpecErrorEnum {
  name: string;
  doc: string;
  cases: SpecEnumCase[];
}

/** Everything the renderer needs to know about one contract. */
export interface ContractSpec {
  /** The contract's crate name, e.g. `zksoroban-verifier`. */
  name: string;
  /** The contract's crate version, e.g. `0.1.0`. */
  version: string;
  functions: SpecFunction[];
  structs: SpecStruct[];
  enums: SpecEnum[];
  events: SpecEvent[];
  errors: SpecErrorEnum;
}

const PRIMITIVE_TYPE_NAMES: readonly PrimitiveTypeName[] = [
  "void",
  "bool",
  "u32",
  "i32",
  "u64",
  "i64",
  "u128",
  "i128",
  "u256",
  "i256",
  "timepoint",
  "duration",
  "address",
  "muxed_address",
  "string",
  "symbol",
  "bytes",
  "error",
  "val"
];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asRecord(value: unknown, what: string): Record<string, unknown> {
  if (!isRecord(value)) {
    throw new Error(`contract spec: expected ${what} to be an object`);
  }
  return value;
}

function asArray(value: unknown, what: string): unknown[] {
  if (!Array.isArray(value)) {
    throw new Error(`contract spec: expected ${what} to be an array`);
  }
  return value;
}

function asString(value: unknown, what: string): string {
  if (typeof value !== "string") {
    throw new Error(`contract spec: expected ${what} to be a string`);
  }
  return value;
}

function asNumber(value: unknown, what: string): number {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    throw new Error(`contract spec: expected ${what} to be an integer`);
  }
  return value;
}

function optionalString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

/**
 * Normalize one `ScSpecTypeDef` (as produced by `xdr.ScSpecTypeDef#toJson`)
 * into the {@link SpecType} model.
 */
export function parseSpecType(json: unknown, what = "type"): SpecType {
  if (typeof json === "string") {
    if (!PRIMITIVE_TYPE_NAMES.includes(json as PrimitiveTypeName)) {
      throw new Error(`contract spec: unknown ${what} "${json}"`);
    }
    return { kind: "primitive", name: json as PrimitiveTypeName };
  }

  const record = asRecord(json, what);
  const keys = Object.keys(record);
  if (keys.length !== 1) {
    throw new Error(`contract spec: expected ${what} to have exactly one key`);
  }

  const key = keys[0];
  const payload = record[key];

  switch (key) {
    case "bytes_n":
      return {
        kind: "bytesN",
        length: asNumber(asRecord(payload, "bytes_n").n, "bytes_n.n")
      };
    case "vec":
      return {
        kind: "vec",
        element: parseSpecType(asRecord(payload, "vec").element_type, "vec.element_type")
      };
    case "option":
      return {
        kind: "option",
        value: parseSpecType(asRecord(payload, "option").value_type, "option.value_type")
      };
    case "tuple":
      return {
        kind: "tuple",
        values: asArray(asRecord(payload, "tuple").value_types, "tuple.value_types").map((value) =>
          parseSpecType(value, "tuple.value_types[]")
        )
      };
    case "map":
      return {
        kind: "map",
        key: parseSpecType(asRecord(payload, "map").key_type, "map.key_type"),
        value: parseSpecType(asRecord(payload, "map").value_type, "map.value_type")
      };
    case "result":
      return {
        kind: "result",
        ok: parseSpecType(asRecord(payload, "result").ok_type, "result.ok_type"),
        error: parseSpecType(asRecord(payload, "result").error_type, "result.error_type")
      };
    case "udt":
      return { kind: "udt", name: asString(asRecord(payload, "udt").name, "udt.name") };
    default:
      throw new Error(`contract spec: unsupported ${what} variant "${key}"`);
  }
}

function parseFields(json: unknown, what: string): SpecField[] {
  return asArray(json, what).map((entry) => {
    const field = asRecord(entry, `${what}[]`);
    return {
      name: asString(field.name, `${what}[].name`),
      doc: optionalString(field.doc),
      type: parseSpecType(field.type, `${what}[].type`)
    };
  });
}

function parseEnumCases(json: unknown, what: string): SpecEnumCase[] {
  return asArray(json, what).map((entry) => {
    const variant = asRecord(entry, `${what}[]`);
    return {
      name: asString(variant.name, `${what}[].name`),
      doc: optionalString(variant.doc),
      value: asNumber(variant.value, `${what}[].value`)
    };
  });
}

/**
 * Build a {@link ContractSpec} from the JSON form of a list of
 * `ScSpecEntry` values (what `xdr.ScSpecEntry#toJson` produces).
 */
export function parseContractSpec(
  entries: unknown[],
  metadata: { name: string; version: string }
): ContractSpec {
  const functions: SpecFunction[] = [];
  const structs: SpecStruct[] = [];
  const enums: SpecEnum[] = [];
  const events: SpecEvent[] = [];
  const errorEnums: SpecErrorEnum[] = [];

  for (const entry of entries) {
    const record = asRecord(entry, "spec entry");

    if (isRecord(record.function_v0)) {
      const fn = record.function_v0;
      const outputs = asArray(fn.outputs, "function_v0.outputs");
      functions.push({
        name: asString(fn.name, "function_v0.name"),
        doc: optionalString(fn.doc),
        inputs: parseFields(fn.inputs, "function_v0.inputs"),
        // The spec encodes a function's return type as a zero-or-one-element
        // list: empty means "returns nothing".
        output:
          outputs.length === 0
            ? undefined
            : parseSpecType(outputs[0], "function_v0.outputs[0]")
      });
      continue;
    }

    if (isRecord(record.udt_struct_v0)) {
      const struct = record.udt_struct_v0;
      structs.push({
        name: asString(struct.name, "udt_struct_v0.name"),
        doc: optionalString(struct.doc),
        fields: parseFields(struct.fields, "udt_struct_v0.fields")
      });
      continue;
    }

    if (isRecord(record.udt_enum_v0)) {
      const udtEnum = record.udt_enum_v0;
      enums.push({
        name: asString(udtEnum.name, "udt_enum_v0.name"),
        doc: optionalString(udtEnum.doc),
        cases: parseEnumCases(udtEnum.cases, "udt_enum_v0.cases")
      });
      continue;
    }

    if (isRecord(record.udt_error_enum_v0)) {
      const udtError = record.udt_error_enum_v0;
      errorEnums.push({
        name: asString(udtError.name, "udt_error_enum_v0.name"),
        doc: optionalString(udtError.doc),
        cases: parseEnumCases(udtError.cases, "udt_error_enum_v0.cases")
      });
      continue;
    }

    if (isRecord(record.event_v0)) {
      const event = record.event_v0;
      events.push({
        name: asString(event.name, "event_v0.name"),
        doc: optionalString(event.doc),
        topics: asArray(event.prefix_topics ?? [], "event_v0.prefix_topics").map((topic) =>
          asString(topic, "event_v0.prefix_topics[]")
        ),
        params: parseFields(event.params, "event_v0.params")
      });
      continue;
    }

    if (isRecord(record.udt_union_v0)) {
      throw new Error(
        "contract spec: union types are not supported by the TypeScript codegen yet " +
          `(contract declares "${asString(record.udt_union_v0.name, "udt_union_v0.name")}")`
      );
    }

    throw new Error(
      `contract spec: unsupported spec entry ${JSON.stringify(Object.keys(record))}`
    );
  }

  if (errorEnums.length !== 1) {
    throw new Error(
      `contract spec: expected exactly one error enum, found ${errorEnums.length}`
    );
  }

  return {
    name: metadata.name,
    version: metadata.version,
    functions: functions.sort((a, b) => a.name.localeCompare(b.name)),
    structs: structs.sort((a, b) => a.name.localeCompare(b.name)),
    enums: enums.sort((a, b) => a.name.localeCompare(b.name)),
    events: events.sort((a, b) => a.name.localeCompare(b.name)),
    errors: errorEnums[0]
  };
}

/**
 * Read the `contractspecv0` custom section out of a compiled contract WASM.
 *
 * Returns the raw XDR payload — a stream of `ScSpecEntry` values, with no
 * length prefix, exactly as `soroban-spec`'s `parse_raw` reads it.
 */
export function readSpecSection(wasm: Buffer): Buffer {
  const section = findCustomSection(wasm, CONTRACT_SPEC_SECTION);
  if (!section) {
    throw new Error(
      `no "${CONTRACT_SPEC_SECTION}" section found in the WASM — ` +
        "is this a compiled Soroban contract?"
    );
  }
  return section;
}

/** Decode a raw contract-spec payload into the JSON form of its entries. */
export function decodeSpecEntries(payload: Buffer): unknown[] {
  return xdr.decodeStream(xdr.ScSpecEntry, payload).map((entry) => entry.toJson());
}

const WASM_MAGIC = 0x6d736100; // "\0asm"

function readVarUint32(bytes: Buffer, offset: number): { value: number; nextOffset: number } {
  let value = 0;
  let shift = 0;
  let cursor = offset;

  for (;;) {
    if (cursor >= bytes.length) {
      throw new Error("truncated WebAssembly module: malformed LEB128 length");
    }
    const byte = bytes[cursor++];
    value += (byte & 0x7f) * 2 ** shift;
    if ((byte & 0x80) === 0) {
      break;
    }
    shift += 7;
    if (shift > 35) {
      throw new Error("malformed WebAssembly module: LEB128 length too long");
    }
  }

  return { value, nextOffset: cursor };
}

/**
 * Find a named custom section in a WebAssembly module.
 *
 * A deliberately small parser: the contract spec lives in a custom section
 * whose payload is a name followed by opaque bytes, and the WASM binary
 * format's section framing is all this needs to understand.
 */
export function findCustomSection(wasm: Buffer, sectionName: string): Buffer | undefined {
  if (wasm.length < 8 || wasm.readUInt32LE(0) !== WASM_MAGIC) {
    throw new Error("not a WebAssembly module: bad magic number");
  }

  let offset = 8;
  while (offset < wasm.length) {
    const sectionId = wasm[offset++];
    const size = readVarUint32(wasm, offset);
    offset = size.nextOffset;

    const sectionEnd = offset + size.value;
    if (sectionEnd > wasm.length) {
      throw new Error("truncated WebAssembly module: section runs past the end of the file");
    }

    if (sectionId === 0) {
      const nameLength = readVarUint32(wasm, offset);
      const nameStart = nameLength.nextOffset;
      const name = wasm.subarray(nameStart, nameStart + nameLength.value).toString("utf8");
      if (name === sectionName) {
        return wasm.subarray(nameStart + nameLength.value, sectionEnd);
      }
    }

    offset = sectionEnd;
  }

  return undefined;
}
